(function(){'use strict';const V=globalThis.PiraV6,D=globalThis.PiraV6Demos,M=globalThis.PiraV7Prototype;const esc=V.escapeHtml;const input=D.ALL_READY;const report=M.model(input);const p=x=>'<p>'+esc(x)+'</p>';const app=document.getElementById('app');
function titleCard(eyebrow,title,subtitle){return '<header class="v7-title-card"><img class="v7-title-band" src="assets/v7/title-band.svg" alt="" aria-hidden="true"><div class="v7-title-content"><span>'+esc(eyebrow)+'</span><h1>'+esc(title)+'</h1>'+(subtitle?'<p>'+esc(subtitle)+'</p>':'')+'</div></header>';}
function resultPage(){return '<section class="v7-page result-page">'+titleCard('情報管理セルフチェック','今回の診断結果')+'<div class="v7-greeting">'+report.greeting.map(p).join('')+'</div><h2>今回の回答状況</h2><table><thead><tr><th>No.</th><th>質問</th><th>今回の回答</th></tr></thead><tbody>'+report.answers.map((a,i)=>'<tr><td>Q'+(i+1)+'</td><td>'+esc(a.question)+'</td><td>'+esc(a.label)+'</td></tr>').join('')+'</tbody></table><h2>今回ご紹介するテーマ</h2><ol class="v7-theme-list">'+report.priorities.map((x,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span>'+esc(x)+'</li>').join('')+'</ol></section>';}
function themePage(){const t=report.themes.find(x=>x.id==='T06');if(!t)return '';const n=String(report.priorityThemeIds.indexOf('T06')+1).padStart(2,'0');return '<section class="v7-page theme-page">'+titleCard('回答に関連する重点テーマ '+n,t.title,t.subtitle)+'<div class="v7-illustrations"><img src="assets/v7/illustrations/15090_color.svg" alt="ランサムウェアのイラスト"><img src="assets/v7/illustrations/18200_color.svg" alt="バックアップのイラスト"></div><p class="v7-intro">'+esc(t.intro)+'</p><section><h2>基本的な知識</h2>'+p(t.common)+'</section><section><h2>'+esc(t.caseTitle)+'</h2>'+p(t.caseText[0])+'<p><strong>'+esc(t.caseText[1])+'</strong></p>'+p(t.caseText[2])+'<div class="v7-impact-cards">'+t.impacts.map(x=>'<div><strong>'+esc(x[0])+'</strong><span>'+esc(x[1])+'</span></div>').join('')+'</div>'+p(t.caseText[3])+'<p><strong>'+esc(t.caseText[4])+'</strong></p></section><section class="v7-principles"><h2>'+esc(t.pointsTitle)+'</h2><ol>'+t.points.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></section><section><h2>日常業務での確認</h2>'+p(t.check)+(t.unknownSupplement?p(t.unknownSupplement):'')+'</section><p class="v7-source">出典：KADOKAWA 2025年3月期 決算関連公表資料</p><section class="v7-tools"><h2>日常業務に役立つツールをご用意しています</h2><p>バックアップは、一度確認して終わりではなく、定期的に取得状況や復元方法を確認することが大切です。</p><p>本レポートの最後にご紹介している「情報管理・セキュリティ年間確認カレンダー」を活用すると、バックアップをはじめとした情報管理の確認事項を、年間の予定として整理できます。</p><p class="v7-tool-label">巻末のお役立ちツール一覧を見る</p></section></section>';}
function t02Page(){const t=report.themes.find(x=>x.id==='T02');if(!t)return '';return '<section class="v7-page theme-page">'+titleCard('回答に関連する重点テーマ 02',t.title,t.subtitle)+'<p class="v7-intro">'+esc(t.intro)+'</p><section><h2>基本的な知識</h2>'+p(t.common)+'</section><section><h2>'+esc(t.caseTitle)+'</h2>'+t.caseText.map(p).join('')+'</section><section class="v7-principles"><h2>'+esc(t.pointsTitle)+'</h2><ol>'+t.points.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></section><section><h2>'+esc(t.factTitle)+'</h2>'+t.fact.map(p).join('')+'</section><section><h2>日常業務での確認</h2>'+p(t.check)+'</section>'+(t.resource?'<p class="v7-tool-label"><a href="'+esc(t.resource.href)+'" target="_blank" rel="noopener">'+esc(t.resource.title)+'（'+esc(t.resource.label)+'）</a></p>':'')+'</section>';}
function regularThemePage(t){const n=String(report.priorityThemeIds.indexOf(t.id)+1).padStart(2,'0');return '<section class="v7-page theme-page">'+titleCard('回答に関連する重点テーマ '+n,t.title,t.subtitle)+'<p class="v7-intro">'+esc(t.intro)+'</p><section><h2>基本的な知識</h2>'+p(t.common)+'</section><section><h2>'+esc(t.caseTitle)+'</h2>'+t.caseText.map(p).join('')+'</section><section class="v7-principles"><h2>'+esc(t.pointsTitle)+'</h2><ol>'+t.points.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol></section><section><h2>'+esc(t.factTitle)+'</h2>'+t.fact.map(p).join('')+'</section><section><h2>日常業務での確認</h2>'+p(t.check)+'</section>'+(t.resource?'<p class="v7-tool-label"><a href="#tool-'+esc(t.resource.id)+'">'+esc(t.resource.title)+'</a></p>':'')+'</section>';}
function referencePage(){return '<section class="v7-page theme-page v7-reference">'+titleCard('セキュリティ参考情報','サイバー攻撃は、対岸の火事ではありません')+'<p>最近、大手企業や公共機関へのサイバー攻撃が相次ぎ、情報漏えいや業務停止などがニュースになっています。しかし、サイバー攻撃は大企業だけの問題ではありません。取引先や委託先とのつながりを通じて、自分たちが被害を受けるだけでなく、自分たちを経由して取引先に影響を与える可能性もあります。</p><h2>IPA「情報セキュリティ10大脅威 2026」</h2><p>IPA（情報処理推進機構）は、組織が注意すべき情報セキュリティ上の脅威を毎年公表しています。2026年版では、次の2つが上位に挙げられています。</p><h3>1位｜ランサム攻撃による被害</h3><p>データを使えなくしたり、盗んだ情報の公開をちらつかせたりして金銭を要求する攻撃です。業務停止や取引先への影響につながることがあります。</p><h3>2位｜サプライチェーンや委託先を狙った攻撃</h3><p>取引先や委託先を足がかりに、別の企業にも被害が広がる攻撃です。自社の対策だけでは防ぎきれないリスクがあります。</p><p class="v7-source">出典：<a href="https://www.ipa.go.jp/security/10threats/10threats2026.html" target="_blank" rel="noopener">IPA「情報セキュリティ10大脅威 2026」 公式資料</a></p><h2>実際に起きたサイバー攻撃</h2><h3>① VPN機器の脆弱性を悪用した不正アクセス（デジタル庁・2026年9月）</h3><p>VPN機器の脆弱性を悪用した侵入が判明し、保守担当者のアカウントを利用した不審なファイルアクセスが確認されました。個人情報漏えいの可能性も報告されています。</p><p>→ 機器の更新だけでなく、アクセス権限の管理や異常の監視も重要です。</p><h3>② 委託先サービスへの不正アクセス（東京都・2026年10月）</h3><p>委託先が利用するメール配信サービスが不正アクセスを受け、関係者の個人情報が漏えいした事例です。</p><p>→ 自社だけでなく、委託先の情報管理や事故発生時の連絡体制も確認しておく必要があります。</p><h2>セキュリティは「技術 × 運用 × 管理」</h2><p>一つの対策だけで、すべてのリスクを防ぐことはできません。システムを守る技術、日々の点検や更新といった運用、そして組織としての管理。これらを組み合わせる「多層防御」が大切です。まずは、自分たちの情報管理やセキュリティ対策の状況を確認してみましょう。</p><p class="v7-source">出典：デジタル庁 公式資料<br>出典：東京都 公式資料</p></section>';}
function toolsPage(){const copy={CALENDAR:['情報管理・セキュリティ年間確認カレンダー','パソコンの更新、バックアップ、アカウント管理など、定期的な確認事項を年間予定として整理できます。'],MAIL:['メール送信テンプレート・確認表','よく使うメールの宛先・本文・添付書類を整理し、送信前の確認漏れを防ぐために役立ちます。'],INCIDENT:['情報漏洩・紛失時の初動対応キット','事故発生時の連絡先、初動手順、対応記録をまとめ、万一の際に備えられます。'],ACCOUNT:['退職・異動時のアカウント確認表','利用サービスごとのアカウント停止、権限変更、ライセンス整理を一覧で管理できます。'],EDUCATION:['職員向け情報セキュリティ教育資料','不審なメール、パスワード、多要素認証など、職員が知っておきたい基本的な対策を学べます。']};return '<section class="v7-page v7-tools-page">'+titleCard('日常業務で使えるお役立ちツール','お役立ちツール一覧')+['CALENDAR','MAIL','INCIDENT','ACCOUNT','EDUCATION'].map(id=>{const r=globalThis.PiraResources.items.find(x=>x.id===id),c=copy[id];return '<article id="tool-'+id+'"><h2>'+esc(c[0])+'</h2><p>'+esc(c[1])+'</p><a href="'+esc(r.files[0].href)+'" target="_blank" rel="noopener">'+esc(r.files[0].label)+'</a></article>';}).join('')+'</section>';}
app.innerHTML='<div class="v7-toolbar"><button id="v7-print" type="button">印刷する</button></div><main class="v7-prototype">'+resultPage()+themePage()+report.themes.filter(t=>t.id!=='T06').map(regularThemePage).join('')+referencePage()+toolsPage()+'</main>';document.getElementById('v7-print').addEventListener('click',()=>window.print());
const calendarLink=document.querySelector('.theme-page .v7-tool-label');if(calendarLink)calendarLink.innerHTML='<a href="#tool-CALENDAR">巻末のお役立ちツール一覧を見る</a>';
document.querySelectorAll('.v7-tools-page article a').forEach(a=>{if(/\.xlsx$/i.test(a.getAttribute('href')))a.textContent='Excel資料をダウンロード';});
document.querySelectorAll('.v7-reference h3').forEach(h=>{const card=document.createElement('section');card.className='v7-reference-card';h.before(card);card.append(h);while(card.nextSibling&&card.nextSibling.tagName==='P')card.append(card.nextSibling);});
const management=[...document.querySelectorAll('.v7-reference h2')].find(h=>h.textContent==='セキュリティは「技術 × 運用 × 管理」');if(management){const grid=document.createElement('div');grid.className='v7-management-grid';grid.setAttribute('aria-hidden','true');grid.innerHTML='<span>技術</span><span>運用</span><span>管理</span>';management.after(grid);}
})();
